<?php
declare(strict_types=1);require getcwd().'/public/index.php';$n=0;function yes($v,$s){if(!$v)throw new RuntimeException($s);echo 'PASS '.$s.PHP_EOL;$GLOBALS['n']++;}function deny($f,$s){try{$f();}catch(InvalidArgumentException){yes(true,$s);return;}throw new RuntimeException($s);}
$db=db();$db->exec("INSERT INTO users(name,email,password_hash)VALUES('Partner Two','partner@test.local','unused')");$other=(int)$db->lastInsertId();$db->exec("INSERT INTO users(name,email,password_hash)VALUES('Administrator','admin@test.local','unused')");$admin=(int)$db->lastInsertId();
function op(array $x):array{return ['operation'=>bin2hex(random_bytes(16))]+$x;}function ticket($ref){$q=db()->prepare('SELECT * FROM support_tickets WHERE reference=?');$q->execute([$ref]);return $q->fetch();}
$create=op(['action'=>'create','subject'=>'Billing question','topic'=>'billing','message'=>'Initial message']);$ref=support_write(1,false,$create);yes(strlen($ref)===16,'partner creates ticket');yes(support_write(1,false,$create)===$ref,'create idempotent');yes((int)$db->query('SELECT COUNT(*) FROM support_messages')->fetchColumn()===1,'single initial message');deny(fn()=>support_write(1,false,array_merge($create,['message'=>'Other'])),'operation conflict');deny(fn()=>support_load($ref,support_user($other),false),'other owner cannot read');deny(fn()=>support_load($ref,null,false),'anonymous cannot read');deny(fn()=>support_write($other,true,op(['action'=>'reply','reference'=>$ref,'version'=>ticket($ref)['version'],'message'=>'bad'])),'non-admin cannot impersonate admin');
$reply=op(['action'=>'reply','reference'=>$ref,'version'=>ticket($ref)['version'],'message'=>'Admin answer']);support_write($admin,true,$reply);yes(ticket($ref)['status']==='awaiting','admin reply awaits partner');support_write($admin,true,$reply);yes((int)$db->query('SELECT COUNT(*) FROM support_messages')->fetchColumn()===2,'reply retry one message');
$note=op(['action'=>'reply','reference'=>$ref,'version'=>ticket($ref)['version'],'message'=>'PRIVATE NOTE','internal'=>1]);support_write($admin,true,$note);yes(ticket($ref)['status']==='awaiting','internal note does not alter status');deny(fn()=>support_write(1,false,op(['action'=>'reply','reference'=>$ref,'version'=>ticket($ref)['version'],'message'=>'bad','internal'=>1])),'partner cannot create internal note');deny(fn()=>support_write(1,false,op(['action'=>'reply','reference'=>$ref,'version'=>1,'message'=>'stale'])),'stale version rejected');
support_write($admin,true,op(['action'=>'status','reference'=>$ref,'version'=>ticket($ref)['version'],'status'=>'closed','priority'=>'high','assignee'=>$admin]));yes(ticket($ref)['status']==='closed'&&(int)ticket($ref)['assignee']===$admin,'status priority assignment');support_write(1,false,op(['action'=>'reply','reference'=>$ref,'version'=>ticket($ref)['version'],'message'=>'Partner again']));yes(ticket($ref)['status']==='open','partner reopens closed ticket');
deny(fn()=>support_write($admin,true,op(['action'=>'status','reference'=>$ref,'version'=>ticket($ref)['version'],'status'=>'open','priority'=>'normal','assignee'=>$other])),'assignee must be current admin');
$contact=support_write(null,false,op(['action'=>'create','name'=>'Claims owner name','email'=>'demo@loyalty.local','topic'=>'other','subject'=>'Public contact','message'=>'Contact inquiry']),true);yes(ticket($contact)['user_id']===null,'contact email does not bind account');deny(fn()=>support_load($contact,support_user(1),false),'same-email owner cannot access contact ticket');deny(fn()=>support_write($admin,true,op(['action'=>'reply','reference'=>$contact,'version'=>ticket($contact)['version'],'message'=>'No unverified email reply'])),'unverified contact email cannot receive thread reply');
deny(fn()=>support_write($admin,true,op(['action'=>'delete','reference'=>$ref,'version'=>ticket($ref)['version'],'confirm_reference'=>'wrong'])),'delete confirmation exact');support_write($admin,true,op(['action'=>'delete','reference'=>$ref,'version'=>ticket($ref)['version'],'confirm_reference'=>$ref]));deny(fn()=>support_load($ref,support_user($admin),true),'deleted hidden from admin direct link');yes((int)$db->query('SELECT COUNT(*) FROM support_messages')->fetchColumn()===5,'soft delete retains stored messages');yes(!(bool)$db->query("SELECT COUNT(*) FROM audit_logs WHERE details LIKE '%PRIVATE NOTE%'")->fetchColumn(),'audit omits message bodies');yes((int)$db->query('SELECT COUNT(*) FROM mail_outbox')->fetchColumn()===0,'unconfigured SMTP sends nothing');echo $n.' support domain assertions passed'.PHP_EOL;
